#include <stdio.h>
#include <string.h>
#include <thinkthen.h>

thinkthen_engine *tt = thinkthen_engine_new();

/* each ticket goes to the team its words name:
   billing, shipping, and account */
const char *texts[] = {"I was billed twice for one order.",
    "My parcel is a week late.", "I am locked out of my account."};
char choose[256];
for (int i = 0; i < 3; i++) {
    snprintf(choose, sizeof choose,
        "{\"choose\": \"Which team owns this?\", "
        "\"options\": [\"billing\", \"shipping\", \"account\"], "
        "\"evidence\": \"%s\"}", texts[i]);
    char *out = thinkthen_call(tt, choose);
    puts(out ? out : thinkthen_error_message(tt));
    thinkthen_free_string(out);
}
